          "第五日，大食军再发起猛攻，葛逻禄部众突然临阵倒戈，自阵后横击唐军。唐军腹背受敌，阵列顷刻大乱，士卒自相蹂践，死亡略尽。高仙芝见大势已去，只得收合残兵，且战且退。归途之中，拔汗那部众阻塞道路，人畜填委，副将李嗣业持大梃冲杀开道，高仙芝方得脱身。及至安西，三万大军仅余数千人，甲仗辎重尽弃敌手。"
