    interpretation: "怛罗斯之战常被后人放大为东西两大帝国的全面对决，实则双方出动的都不过是边区驻军，战争规模有限，胜负亦未撼动任何一方的根基。唐军之败，败因不在兵锋不利，而在边政败坏：高仙芝贪石国之富，毁约袭杀，失信于西域诸国，葛逻禄临阵倒戈，正是藩国信任崩塌的集中爆发。就疆域而言，此战并未使唐朝立即失去安西，四镇仍存续近半个世纪；就文明而言，其影响却远超战场——造纸术经战俘西传，深刻改变了伊斯兰世界乃至欧洲的知识传播方式。悲剧之中意外开出的文明之花，或许正是这场战争最值得后人品味的余韵。",
