    interpretation: "甘露之变非一二人之失，乃制度之弊。自代宗以神策军归宦官典掌，中尉、枢密遂成定职，宦官据天子之私兵，外结藩镇，内制百官，废立皆出其口。文宗欲以南衙文臣、金吾卒长除北司之帅，强弱悬殊，已属冒险；而李训轻躁寡谋，欲专功而先期发难，伏兵单薄，临阵自乱，韩约变色流汗，风起幕掀，遂使一身之胆气尽付东流。事变之后，士大夫遇宦官如虎，牛李党争各引中尉为援，皇权沦为宦官之附庸。唐自安史乱后，藩镇割据于外，宦官专擅于内，二者交相为患，甘露之变正是此局不可逆转之明证，唐之末运由是而定。",
