          "唐宪宗李纯即位后，以复兴皇纲为己任，先平西川刘辟、夏绥杨惠琳、镇海李锜，声势大振。吴少阳存时，尚畏威怀惧；吴元济无名擅立，恰成朝廷用兵之口实。元和十年（815年）正月，宪宗下诏削吴元济在身官爵，命宣武节度使韩弘充淮西诸军行营都统，调集十六道兵马进讨，淮西之役遂起。"
