    interpretation: "淮西之役的胜负，看似决于雪夜一击，实则成于三年经营。其可记者有三：裴度督师，奏罢中使监军，统一诸道号令，将帅始得自专，此制度之胜；李愬释丁士良、用李祐，以敌将攻敌城，尽得蔡州虚实，此攻心之胜；李光颜、乌重胤缠斗洄曲，牵制董重质重兵，蔡州空虚方有可乘之机，此全局之胜。就长远而言，此役将元和中兴推向鼎盛，却未重塑支撑中央的长效军政结构，兵权财权仍外重内轻，故穆宗朝河朔旋复叛失，中兴如昙花一现。至于李愬雪夜奔袭，上承邓艾偷渡阴平，下为千古奇袭典范，则其战法之影响，又不仅在唐一代矣。",
