          "八月诏令大毁，朝廷遣御史分道督责。凡非应留之寺，限期拆撤，州县承风，往往过当。寺宇材瓦以葺公廨驿舍，铜铁佛像熔铸钱币与农器，寺院财货田产悉数没官。毁拆之酷，史所罕见；一时缁流顿失所依，长安城中僧尼裹足，诸寺钟鼓绝响。",
          "此番沙汰并不仅及于佛徒。大秦（景教）、祆教、摩尼教寺院同遭废毁，教士勒令还俗，自西传入之三夷教自此一蹶不振。日本天台宗僧圆仁时在长安，亲历其事，于《入唐求法巡礼行记》中逐日记下敕使搜寺、经像焚弃之状，为后世留下亲历者之记录。"
