          "然史书所载田亩之数动称数千万顷，以唐代垦田总数计之，显属夸饰；僧尼二十六万余之数，则合天下滥度之实。要之，此役之利在于籍户增税，其害则在于执行惨急，经卷散佚，古刹名蓝摧于一旦，士大夫多有非议之者。",
          "沙汰之后，僧尼簿籍悉隶有司，祠部之职并省，供养、烧身、讲经诸事并遭禁断，佛教遂被逐出宫廷与都会，退入山林。会昌一朝府库虽以括佛而充，然未几武宗崩，新君继统，尽反其政，所得之利亦随政潮而俱往。"
