          "杨国忠惊惧，策马奔逃，军士拍马追上，杀之于驿门之外，随即屠割支体，以枪挑其首级悬于驿门示众。御史大夫魏方进闻变赶来斥责，亦被乱兵所杀；左相韦见素被殴伤头部，赖众人呼救得免。杨国忠之子太常卿杨暄，以及韩国夫人、秦国夫人，皆同时被杀于道旁。一时血溅驿门，杀声震天。玄宗闻变，拄杖出驿门慰劳将士，令其收队，军士不应——众怒未息，因为「贼本」尚在。"
