          "此狱一兴，朝野哗然，士林皆谓之冤。牛僧孺、李宗闵既以直道见抑，反得重名，数年间渐以才望进用，至长庆、大和中并登宰辅。而李吉甫之子李德裕，少以门荫补校书郎，元和末已为翰林学士，典掌诰命。父辈所结之怨，遂演为两朝朋党：一为牛僧孺、李宗闵之进士科第集团，一为李德裕之山东士族门荫集团，牛李之争自此伏脉。"
