          "此案首发者段文昌，而李德裕、李绅实助成之，李宗闵由此深恨三人；牛僧孺等亦上疏为钱徽鸣冤，朝议汹汹。自是各分朋党，援引同类，倾轧异己。然所谓牛李二党，初非科举、门荫判然两途：牛党杨嗣复为名臣杨於陵之子，李党李绅亦以进士入仕，泾渭本不分明，要之恩怨相寻、权势相倾而已。长庆科场案，遂为四十年朋党之争之正式开端。"
