          "大和五年（831），吐蕃维州守将悉怛谋率众请降于西川。李德裕以维州当西山之冲，据险可制吐蕃，上疏请受其降。牛僧孺在朝，力主还之，谓朝廷既与吐蕃通好，纳叛将则失信远夷，且启兵衅。文宗竟从僧孺议，诏李德裕送还维州，并执悉怛谋归于吐蕃，吐蕃尽诛其众。李德裕由是深怨牛僧孺，两党之隙，遂不可复合。",
          "此后数年，牛僧孺出镇淮南，李德裕一度入相，复为李宗闵所排，再出浙西。大和九年（835），李训、郑注用事，甘露之变起，宦官仇士良益专朝权。文宗受制于北司，又苦南衙朋党，无可奈何。开成元年（836），李德裕自浙西入相，与李宗闵、杨嗣复同列庙堂，互执意见，更相排摈。开成年间，两党进退无常，文宗尝对近臣叹息，以去朋党为难于去河北藩镇。"
