          "会昌六年（846）三月武宗崩，宣宗即位。四月，罢李德裕相，出为江陵尹、荆南节度使。白敏中、令狐绹相继当国，牛党尽复旧位。大中元年（847），李德裕再贬潮州司马；二年（848），又贬崖州司户参军；三年（849），卒于崖州贬所，年六十三。牛僧孺虽得生还，未几亦谢世。自元和三年至此，恩怨相寻凡四十载，终以李党覆灭、牛党全胜收场，而唐之国势，亦于是役中销磨殆半。"
