    interpretation: "牛李党争之实质，史家颇有异同。陈寅恪以牛党为进士科新贵、李党为山东旧族门荫集团，视为两股社会阶层之争；然细考人物，牛党杨嗣复、李珏多名族子弟，李党李绅、陈夷行亦进士出身，泾渭并不判然，近时学者多以为权势倾轧、人事恩怨为主，阶层之争为辅。要之，两党对宦官皆依附利用：李宗闵结杨承和，李德裕亦交通神策中尉，君子小人，固无截然之界。其害则灼然可见。四十载中，宰相进退一视朋党，政令朝定夕改；维州得失、边防大计，皆成党争筹码。人才困于门户，忠正之士无从自立；宦官坐收轻重之权，南衙益弱而北司益强。故史家以牛李党争为唐祚倾颓之一因，与藩镇、宦官、流民并列，为中晚唐四大痼疾。",
