    dynasty: "唐",
    era: "长庆元年",
    year: {
      start: 821
    },
    summary: "长庆元年（821），唐穆宗与吐蕃赞普赤祖德赞互派使臣，先会盟于长安西郊，翌年唐使刘元鼎入蕃，复会盟于逻些（今拉萨），长庆三年（823）立碑于大昭寺前，世称「唐蕃舅甥和盟碑」。盟文重申太宗、中宗以来和亲之谊，约定各守旧界、互不侵伐，并开互市以通有无。这是唐蕃二百余年间第八次会盟，也是成效最著的一次：此后双方大规模战争基本止息，使臣商旅往来不绝，享近六十年相对和平。会盟碑历经近一千二百年风雨，至今犹立于拉萨，是汉藏友好交往的实物见证。",
    background: "安史之乱（755—763）爆发后，唐朝尽撤河陇戍兵东调平叛，吐蕃趁虚蚕食河西、陇右数十州。广德元年（763），吐蕃二十万众一度攻入长安，唐代宗出逃陕州，赖老将郭子仪收合残部、联络回纥，方复京师。此后数十年，唐蕃在凤翔、泾原、盐州一线反复拉锯：建中四年（783），双方会盟于清水，划定疆界；贞元三年（787），吐蕃于平凉劫持唐朝会盟使臣浑瑊，和局旋破。战事久拖不决，唐朝财赋困乏，吐蕃亦疲于奔命，河陇吐蕃奴部屡有怨叛。九世纪初，赤祖德赞（彝泰赞普）在位，吐蕃内部矛盾丛生，亟需喘息；唐宪宗平定淮西、淄青后国家元气大伤，穆宗即位，朝野上下俱盼息兵休民。双方重修旧好之意一拍即合，遂有长庆会盟之举。",
    chapters: [
      {
        heading: "长安西郊，歃血定盟",
        paragraphs: [
          "长庆元年（821）九月，吐蕃遣使臣钵阐布·勃阑伽允丹、论讷罗等入长安，奉赞普赤祖德赞之命请盟。唐穆宗许之，命宰相崔植、杜元颖、王播、韩皋、王涯、杜兼等十七人，与吐蕃使臣于十月十日会盟于长安西郊。唐朝对此次会盟极为郑重，除宰臣外，尚书以下、神策军使、诸卫将军、中使皆预其事，仪仗鼓吹俱全。盟文开篇即追述唐太宗以文成公主妻松赞干布、唐中宗以金城公主妻赤德祖赞之事，称唐蕃「代为婚姻，好尚相类」，明言此番会盟并非城下之盟，而是甥舅之邦重叙旧好。",
          "会盟按古礼进行，双方登坛歃血，告祭天地山川。盟文载明：唐蕃边界「悉依旧界」，即大体维持清水会盟所定——唐守泾州、陇州以西弹筝峡一线，吐蕃守原州、会州一带，中间地带各不得侵扰。同时又约定互市往来，唐朝以丝织品、茶叶易吐蕃马匹牛羊，边民各得其所。盟文末尾申明，自今以后「屏去兵革，宿忿旧恶，廓然消除」，双方使臣往来不得阻拦。长安会盟既成，唐朝随即着手准备遣使入蕃，在赞普牙帐前复盟，以昭信义。"
        ]
      },
      {
        heading: "元鼎西行，逻些复盟",
        paragraphs: [
          "长庆二年（822），唐朝以大理卿兼御史大夫刘元鼎为入蕃会盟使，随吐蕃使臣论讷罗西行。刘元鼎一行逾陇山，渡黄河，经兰州、鄯州，沿青海湖北岸西行，再转向南，历数千里跋涉，终于抵达吐蕃都城逻些（今拉萨）。这是继文成、金城两公主之后，唐朝赴逻些级别最高的使团之一。赤祖德赞率大臣出迎，于牙帐中盛礼相待。双方再度会盟，盟文与长安之盟相呼应，重申「舅甥和同为一家」之意。吐蕃方面对此盟极为看重，赞普以下将帅大臣皆预盟誓，载书于册，告祭于神祇之前。",
          "据刘元鼎归后所述，吐蕃届时已尊崇佛法，赤祖德赞以佛法治国，朝中大事多与僧相钵阐布商议。刘元鼎在逻些亲见吐蕃官制、礼仪、服饰、居处，归而著为纪行，为后世留下关于九世纪吐蕃社会的珍贵记载。会盟之后，吐蕃遣使随刘元鼎入长安谢恩，并献马匹、金银器物。至此，长安、逻些两会盟相互印证，唐蕃和好之局乃定。此后数十年间，双方使臣往来频繁，每逢赞普或皇帝即位更替，皆有聘使报聘，渐成定制。"
        ]
      },
      {
        heading: "立碑大昭寺，文载甥舅情",
        paragraphs: [
          "长庆三年（823），「唐蕃舅甥和盟碑」立于逻些大昭寺门前。碑身通高约一丈有余，正方刻藏文，碑侧刻汉文，两种文字并镌，昭示于众。碑文首叙唐蕃甥舅之源：唐太宗贞观十五年（641）以文成公主嫁松赞干布，唐中宗景龙四年（710）以金城公主嫁赤德祖赞，「外甥是先帝舅宿亲」，累代婚姻，恩义相连。继而记述长庆会盟始末：唐朝遣使入蕃，吐蕃亦遣使入唐，「商议叶同，务令万姓安泰，所思如一」。",
          "碑文最后申明盟约之旨：唐蕃「和同为一家」，各守封疆，不相侵伐，往来通使，道路无阻；碑石既立，历代赞普、皇帝皆不得违毁。此碑历经近一千二百年风雨，至今仍立于大昭寺前，是拉萨城里最古老的汉文石刻之一。碑文所载，与《旧唐书》《新唐书》关于长庆会盟的记述互为印证，是研究唐蕃关系的第一手实物。碑上汉藏文字并镌的形式，也说明当时双方在政治、文化上的深度交融。"
        ]
      },
      {
        heading: "息兵通市，惠及两端",
        paragraphs: [
          "长庆会盟之后，唐蕃之间虽偶有摩擦，但大规模战争基本止息。会盟所定互市继续维持，陇州、赤岭等地互市不绝：吐蕃良马源源输入中原，唐朝丝织品、茶叶大量进入高原，长安与逻些之间使臣、商旅往来频繁。唐朝得以从西线抽身，专力处理河北藩镇与内部财政；吐蕃亦得喘息，赤祖德赞得以推行佛法、整顿内部。大中二年（848），沙州张议潮起兵归唐，河陇吐蕃统治瓦解，唐蕃关系进入新阶段，但双方互通使节的惯例仍未断绝。",
          "从更长时段看，长庆会盟的意义不止于息兵。唐末五代，吐蕃政权分崩离析，中原亦陷入分裂，西藏地方与中央政权的关系一度松弛；但唐蕃舅甥之好所积累的政治传统与文化联系并未断绝，为后来元朝西藏正式纳入中央王朝管辖奠定了历史基础。会盟碑上「舅甥和协，扫彼旧怨」八个字，不独是两朝帝王的盟誓，也凝聚了汉藏两族人民渴望和平、互通有无的共同愿望，至今仍矗立在大昭寺前，见证着这段历史。"
        ]
      }
    ],
    interpretation: "长庆会盟的成功，不全在盟文辞藻，而在于双方都到了不得不和的关口。唐朝经安史之乱，河陇尽失，京畿长年处于吐蕃骑兵威胁之下，虽筑盐州城、修邠宁防线，终不能彻底解决问题；吐蕃虽武功极盛，但连年征发使属部离心，军中将帅渐成尾大不掉之势，赤祖德赞以佛法治国，亦需外部和平以整顿内部。会盟以「舅甥」为名，既是政治盟约，也是文化认同：双方都承认唐蕃之间有血亲与礼仪上的特殊关系，并非寻常敌国之交。这一盟约维持了近六十年的相对和平，使双方各自腾出手来处理内部危机，也为后世中央政权处理与西藏地方的关系提供了范式。",
