    interpretation: "唐灭东突厥，名为雪渭水之耻，实为太宗「中国既安，四夷自服」方略之结果：先以三年休养生息，待敌天灾、内乱、部族叛离并作，而后以最小代价一战定功。李靖之所以制胜，全在「以正合、以奇胜」三字：三千骑深入敌境是奇，乘其请降不备而夜袭阴山更是行险，置唐俭生死于不顾，深得「将在外君命有所不受」之精髓，太宗亦不以为罪，反加赏异，可见贞观君臣相得。太宗处置降众，不诛颉利、不裂其地，而设都督府羁縻，以夷治夷，开唐朝华夷一家之局；「天可汗」号实令草原共主与中原天子合于一身，北族政权第一次真正纳入中原秩序，唐遂为东亚霸主，贞观之治由此奠定。然突厥部众内徙河南，离故土、失故俗，亦为高宗时后突厥复国埋下伏笔，功业与隐患，往往并存。",
