    interpretation: "文成公主入藏，表面上是帝王家的婚嫁，内里是两个强权的战略安排。贞观中叶，太宗正经营西域、用兵辽东，无暇长期屯重兵于西南；吐蕃方兴，统一高原，其锋正锐。和亲使唐廷以最小代价稳住西南，使吐蕃在太宗朝数十年间未大举东进；吐蕃则借联姻获得中原的工匠、典籍与贸易通道，加速自身文明化，这是一场双赢的政治安排。文成公主带去的佛像、经典、工匠与种子，把汉地的技术、信仰与生活方式带入高原，大昭寺的觉阿像与唐柳至今犹存；唐蕃「舅甥」名分一开，便为后世会盟与长庆碑文所继承。千载之下，这段和亲仍是汉藏交融史上最深的印记。",
