      {
        heading: "双面治术：科场与诏狱",
        paragraphs: [
          "武周之政，最重选人。载初元年（690）二月，太后亲策贡士于洛城殿，殿试自此而始。她大开制科，屡下求贤之诏，士子由四方奔集神都，一科所录动辄数十人。长安二年（702），又置武举，以长垛、步射、马枪之类选取将才。狄仁杰以明经入仕，在天授、长寿间官至宰相；姚崇、宋璟、张说、郭元振之辈，亦皆于武周一朝崭露头角，后来多为开元前后的名臣宰辅。她又选文学之士入禁中修撰，号「北门学士」，分宰相之权，备顾问之任。",
          "治民以农为先。垂拱二年（686），武后亲撰《兆人本业》三卷，以耕织之法颁示天下州县，劝课农桑。边事上，长寿元年（692），王孝杰大破吐蕃，复龟兹、于阗、疏勒、碎叶安西四镇，徙安西都护府于龟兹，发兵戍守；长安二年（702），又置北庭都护府于庭州，镇抚西突厥诸部。永徽三年（652）天下三百八十万户，至神龙元年（705）已近六百一十五万户，五十年间户口几增一倍。其间虽屡兴大狱，田亩未荒，赋役未失，此为明证。",
          "然其治术的另一面，是十余年不曾断绝的诏狱。铜匦既开，索元礼、周兴、来俊臣、侯思止之徒竞以罗织邀功，来俊臣更撰《罗织经》数千言，经其手株连者动辄数百千家。王公大臣一旦入网，酷刑逼认，破家灭族者不可胜数。天授二年（691），来俊臣按问周兴，对以「请君入瓮」之计，周兴流放岭南、死于道上，索元礼亦毙于狱中。武后用酷吏，原以威慑异己、稳固新朝，待皇权既定，工具即弃。神功元年（697）六月来俊臣伏诛，其党始散，告密之风方才渐息。"
        ]
      }
