    interpretation: "武周代唐，不是寻常的改朝换代。一个妇人临朝称帝，面对的是李唐宗室与关陇旧勋的合法性质疑，她的应对是双线的：一条是神话与符瑞，造「曌」字、颁《大云经》、追尊周文王为始祖，把武氏包装成上古圣王之后、弥勒下生之主；一条是制度与人事，开殿试、设武举、广制科，把选官之权从门阀手中收归皇权，以新兴士人替换旧族子弟。酷吏不过是皇权清算异己的临时工具，周兴、来俊臣辈煊赫一时，势成即弃。她拔用的狄仁杰、姚崇、宋璟、张说等人，后来撑起了开元盛世；殿试与武举自此成为科举定制。神龙政变虽复唐号，制度、人材、都城格局皆相沿未改，故武周十五载，实是唐史中一段，而非断然之两朝。",
