    interpretation: "永贞革新之败，非尽人事之失，实势所必至。顺宗中风失音，皇权悬虚，新政所恃惟翰林承旨与中书奉行，并无兵权为根本。而其所触犯者，乃代宗以来宦官典神策军、掌枢密之大柄，此权既可劫制天子，区区翰林学士自无从抗衡。王叔文以棋待诏骤揽大权，资浅望轻，所结党羽又杂，韦执谊中变，其败宜矣。然罢宫市、禁五坊、停进奉，皆为恤民息弊之政；中唐积弊非至宪宗不能理，而宪宗之治实承其端绪。柳宗元、刘禹锡身谪而名益彰，其文章气节，转因永贞一役而传诵千载。",
