      {
        heading: "河朔廓清，中兴落幕",
        paragraphs: [
          "吴元济既平，河北震怖。元和十三年（818），王承宗累表请罪，献德、棣二州，遣子入侍，输贡赋如故事。淄青平卢节度使李师道据郓州十二州，初闻淮西败，亦请纳质献地，旋惧而悔之。宪宗怒其反覆，是年七月下诏讨之，命田弘正、李愬、李光颜等数道兵马进讨。元和十四年（819）二月，官军围郓州，都知兵马使刘悟知李师道必败，倒戈回师，入城斩之，传首长安。朝廷分淄青十二州为三道：郓、曹、濮为一道，青、淄、齐、登、莱为一道，兖、海、沂、密为一道，各置节度使。至此，自安史之乱六十余年，方镇无不内惧，唐室威令一时复振。",
          "淄青既平，河朔三镇中，魏博田弘正、成德王承宗皆奉朝命，卢龙刘总虽怀两端，亦上表输诚，不敢公然抗旨。元和十五年（820）正月，宪宗正欲复河朔旧疆，忽暴崩于大明宫中和殿，年四十三。时人皆传言宦官陈弘志等弑逆，史氏讳而不书；穆宗李恒即位，朝政操纵于王守澄之流。中兴之局，遂失其主。",
          "穆宗君臣不知兵，处置河朔乖方。长庆元年（821），卢龙军囚节度使张弘靖而立朱克融，成德军杀田弘正而立王廷凑，朝廷调诸道兵讨之，再败，河朔三镇得而复失。自是朝廷威令复坠，元和成果尽付东流。故史家论元和中兴虽盛，实系于宪宗一人之身，人亡政息，良可慨叹。"
        ]
      }
