    interpretation: "元和中兴的深层支撑是三样东西：德宗以来两税法与榷盐之利积聚的财赋，以神策军为核心的中央武力，以及宪宗用人不疑的宰相班子。杜黄裳主兵略，李绛善谋略，武元衡以身殉国，裴度督师亲征，中枢稳定使削藩得以贯彻始终。但这场中兴的限度同样明显：唐军屡胜，靠的是以藩镇制藩镇——调魏博田弘正平淄青，复以刘悟代李师道，旧镇虽去，新镇之患仍在；河北赋税不入、将士世袭的结构未变。宪宗一死，穆宗朝措置乖方，河朔再叛，威令得而复失。故元和中兴实为安史之乱后六十年间一次回光返照式的重振：它表明中央仍有平定跋扈藩镇的实力与意志，却终未能建立约束骄兵悍将的长效机制。",
