          "天祐元年（904年）正月，朱温以长安残破、不便控制为名，请昭宗迁都洛阳，拆毁长安宫室民居，驱赶士民东行，昔日帝都遂成丘墟。昭宗至洛阳，左右侍卫尽为朱温之人，知事不免，常对侍臣流涕。同年八月壬寅夜，朱温遣蒋玄晖与朱友恭、氏叔琮率兵入宫，弑昭宗于椒殿，昭宗年仅三十八岁。事后朱温杀朱友恭、氏叔琮以塞责，旋立昭宗第九子、辉王李祚为帝，更名柷，是为唐哀帝，改元天祐，自己则进封梁王，加九锡，篡唐之势已成。",
          "为清除朝中反对势力，天祐二年（905年）六月，朱温采纳幕僚李振之言，将宰相裴枢、崔远、独孤损、陆扆等朝臣三十余人贬杀于白马驿（今河南滑县），投尸黄河，史称「白马驿之祸」。李振因屡试不第，尤恨衣冠之士，称此辈自号清流，不如投入黄河使为浊流。经此一劫，唐朝残余的士族朝臣集团几被诛除殆尽，朝堂为之一空，朱温代唐再无阻力。"
