          "朱温篡唐并非一姓之兴衰，而是晚唐藩镇格局演变的终局。自安史之乱后，跋扈藩镇行之百余年，至朱温以宣武节度使身份直接篡位，不过是把藩镇「兵强马壮者当为之」的逻辑推至极端。此后五十三年间，中原历经梁、唐、晋、汉、周五个短命王朝，南方与河东裂为前蜀、吴、吴越、闽、楚、南汉、南平、后蜀、南唐、北汉等十国，中国进入五代十国的大分裂时期。开平二年（908年）二月，朱温又鸩杀唐哀帝于曹州，谥曰哀皇帝，唐朝最后的血脉亦被斩断。"
