          "然禄山外示愚憨，内实狡黠。见玄宗春秋高，颇怀观望；厚赂中官，刺探禁中语；于范阳北筑雄武城，名为御两蕃，实贮兵仗粮谷；养同罗、奚、契丹降兵八千为假子，皆骁锐敢死；又以刘骆谷留京师，专主伺察朝廷动静。李林甫在位时，禄山犹有惮，每见之，虽盛冬亦汗流浃背。及杨国忠代相，无术以制，乃数于帝前言禄山必反，又屡以事撼之。禄山惧且怒，益治兵。帝使中使辅璆琳伺之，受其金，还言无反状。由是上下相欺，乱益迫。"
