          "先此，禄山已于至德元载（756）正月僭位洛阳，国号大燕，建元圣武，署置百官。及潼关既破，京师大骇，玄宗仓皇西幸，至马嵬驿，六军不发，将士杀杨国忠，缢杀杨贵妃，乃得行。禄山遂入长安，大索百官、宫人、乐工三日；凡扈从大臣、宗室之留京者，多被屠戮，其兵四出剽掠，自黄河两岸至于关中，烟火千里。然颜杲卿、颜真卿起兵河北，郭子仪、李光弼复常山、赵郡，断其归路，禄山首尾不能相顾，势稍困。"
