          "然禄山虽死，乱未平也。安庆绪暗弱，能抚下者莫如史思明。及官军收复长安、洛阳，思明据范阳，旋杀庆绪自立，乱事复延。直至广德元年（763）正月，史朝义传首京师，安史之乱始平，凡七年有余。而河北诸将，大抵皆禄山旧部，名虽归朝，自署官吏、不供贡赋、父子相袭，朝廷亦以姑息处之，藩镇割据之局成矣。自天宝十四载至于五代，河北半化于胡，中央号令不复及于河朔。论者谓：禄山一身虽灭，其所启之祸，与唐相终始焉。"
