    interpretation: "杜如晦的历史地位，须置于唐初政治转型的脉络中理解。其一，他是秦王府功臣集团的代表人物。太宗以秦王夺嫡，即位后即以秦府旧僚为执政根基，杜如晦由府僚而宰相，正是这一政权班底构建的关键一环。其二，他与房玄龄的互补，揭示了成熟决策机制的内在结构：房玄龄善谋，集众议而条理之；杜如晦善断，临大事而一言决。谋断相须，贞观中枢因此运转高效、少有壅蔽。其三，贞观三四年间，房、杜裁定的官制、律令与考课之法，奠定有唐一代典章的雏形，贞观之治的制度骨架，半成于此。其四，其人寿止四十六岁，正当盛年而早卒，太宗恸哭废朝，凌烟阁画像高居第三。论者每叹天不假年，使贞观初年最善决断的宰辅，未能尽展其才。",
