    summary: "房玄龄（579—648），名乔，字玄龄，齐州临淄人，唐朝开国名相。隋末杖策投李世民，任渭北道行军记室参军，为秦王府十八学士之首。武德九年参与玄武门之变，功居第一。贞观朝任中书令、尚书左仆射，居相位二十余年，与杜如晦并称「房谋杜断」。主持厘定《贞观律》，监修《晋书》一百三十卷，是贞观之治的行政核心。贞观二十二年病逝，享年七十岁，赠太尉，谥文昭，陪葬昭陵，图形凌烟阁。",
    background: "房玄龄生于北周大象元年（579年），父房彦谦仕隋至司隶刺史，以清廉善政闻名。玄龄自幼博览经史，开皇十七年（597年）十八岁举进士，深得隋朝吏部侍郎高孝基赏识，称其必致远大。隋炀帝大业年间，三征高句丽、营建东都、开凿运河，海内骚动，群雄并起。大业十三年（617年），李渊于太原起兵，李世民率军入渭北，房玄龄杖策谒于军门，从此追随李世民。这一选择既决定了他个人的命运，也为贞观一朝的行政班底埋下伏笔。",
    chapters: [
      {
        heading: "渭北杖策，秦府首臣",
        paragraphs: [
          "隋大业十三年（617年），李渊太原起兵，西进关中，李世民率部入渭北。房玄龄闻讯，杖策谒于军门，时年三十九岁，一见如故，被署为渭北道行军记室参军。此后数年，玄龄随李世民平定薛仁杲、刘武周、王世充、窦建德，每平一处，众将竞收金帛珍货，玄龄独留意人物，将可用之才延揽入幕。后来名垂贞观的杜如晦，即由玄龄力荐而得重用。",
          "武德四年（621年），李世民平定中原，开文学馆于宫西，延揽才学之士十八人，号十八学士，以房玄龄为首，朝野瞩目。武德末年，太子李建成、齐王李元吉与秦王矛盾激化，建成忌惮玄龄、如晦之谋，谮于高祖，二人被斥逐出秦府。武德九年，局势危急，太宗命长孙无忌密召玄龄、如晦还府，计议大事，为玄武门之变埋下伏笔。"
        ]
      },
      {
        heading: "玄武定难，功居第一",
        paragraphs: [
          "武德九年六月初四（公历626年7月2日），玄武门之变爆发，李世民诛李建成、李元吉，控制局势。事定论功，房玄龄与长孙无忌、杜如晦、尉迟敬德、侯君集五人功居第一，玄龄食实封一千三百户。八月，高祖内禅，太宗即位，改元贞观，以秦府旧臣为班底组建朝廷，贞观政权自此奠基。",
          "贞观元年（627年），房玄龄任中书令，掌最高政务。贞观三年（629年），拜尚书左仆射，位居宰相，更封魏国公，监修国史。贞观十一年（637年），太宗定功臣世袭刺史之制，玄龄改宋州刺史，徙封梁国公。此后居相位二十余年，总理百司，直至贞观二十二年病逝，为有唐一代任期最长的宰辅之一。"
        ]
      },
      {
        heading: "房谋杜断，贞观枢机",
        paragraphs: [
          "房玄龄善谋，杜如晦善断，时人并称「房谋杜断」。贞观三年，杜如晦拜尚书右仆射，与玄龄共掌朝政，同心徇国。贞观四年如晦早逝，玄龄独任仆射十余年。史书形容他「任总百司，虔恭夙夜，尽心竭节，不欲一物失所」；他明达吏事而饰以文学，闻人有善若己有之，不以求备取人，不以己长格物，故贞观一朝人才蔚然。",
          "与魏征以谏诤显名不同，房玄龄以行政见长。太宗巡幸、征伐，玄龄或侍从、或留守，朝廷常务、人才进退、州县奏报多由其裁决。贞观十七年（643年），太宗命图画功臣二十四人于凌烟阁，玄龄名列其中。贞观十九年（645年），太宗亲征高句丽，玄龄留守长安，总理后方军国事务，粮械调度不绝。",
          "贞观二十二年（648年），玄龄病重，太宗亲临其第，握手诀别。七月卒，享年七十岁，赠太尉、并州都督，谥文昭，陪葬昭陵，配享太宗庙庭，备极哀荣。一代良相，至此谢幕。"
        ]
      },
      {
        heading: "厘定律令，监修晋书",
        paragraphs: [
          "贞观初年，太宗命长孙无忌、房玄龄等厘定律令，历十余年删改，于贞观十一年（637年）颁行《贞观律》十二篇五百条，并修成令、格、式，死刑条目较隋律大幅减少。玄龄审定法令，意在宽平，由此奠定唐代法制根基。此后《永徽律疏》《唐律疏议》一脉相承，影响远及日本、朝鲜。",
          "贞观十八年（644年），太宗以十八家晋史体例不一、善恶失实，诏修《晋书》，以房玄龄为总监，令狐德棻、敬播等十八人同修。历时不及三年，贞观二十年（646年）成书一百三十卷，叙两晋一百五十余年史事，为二十四史中唯一的官修纪传体史书。宰相监修史书之制，亦自此而兴。"
        ]
      }
    ],
    interpretation: "贞观之治向为后世所重，其所以致治，不仅在于太宗纳谏与轻徭薄赋，更在于律令格式这一制度骨架。房玄龄主持厘定贞观律令，使唐承隋制而益趋宽平，定令、格、式，为《唐律疏议》铺路，影响远及东亚。他以秦府记室起家，随太宗从战时幕府转入文官政府，身居仆射二十余年，是贞观行政的实际运转者。与魏征之谏诤、李靖之武功并立，玄龄代表的是宰相的治事之能。然身后未久，其子房遗爱卷入谋反案，永徽四年（653年）被诛，房氏配享太庙之典随之罢废，亦见贞观政治遗产在权力交接中的脆弱。",
