          "开元十一年（723年），宰相张说建策召募壮士充宿卫，得十二万人，号「长从宿卫」，后改称「彉骑」，募兵渐代府兵。开元二十五年（737年），朝廷诏令边镇戍卒一律改为长镇招募。天宝八载（749年），停折冲府上下鱼书，府兵制正式终结。自贞观十年定制至天宝八载罢废，前后历一百一十三年。",
          "府兵既废，边镇节度使自募长驻之兵，兵为将有；中央彉骑渐趋废弛，京师空虚。天宝十四载（755年），身兼范阳、平卢、河东三镇节度使的安禄山，率所募边兵叛乱，两京陷落。募兵制下将专其兵、兵附其将，终成藩镇割据之局，唐由盛转衰。"
