    interpretation: "府兵制是唐王朝以农业社会为基础的军事设计，核心逻辑是「以田养兵、以兵卫田」：国家授田于民，征其服役；兵役与土地、户籍、租调捆绑，故养兵不耗国帑。兵散于府、将归于朝，军权集于天子，杜绝将帅私兵。此制依赖三个条件：均田足授、户籍严密、徭役有度。一旦人口增殖、土地兼并、戍役失期，农民逃亡，制度即随之崩塌。其兴衰昭示一条规律：军制必须与经济、财政制度相表里。府兵废而募兵兴，军费激增而兵为将有，终为安史之乱与藩镇割据埋下祸根。明代卫所制虽仿其意，亦同因土地而坏。",
