    year: {
      start: 624
    },
    summary: "均田制是唐代立国的土地制度。武德七年（624年），唐高祖颁行《田令》：丁男年十八以上授田一顷，其中永业田二十亩可传子孙，口分田八十亩死后还官；老男、废疾、寡妻妾等减授。国家将无主荒地按户授予农民，再以租庸调征收粟绢与徭役，把土地、户籍、赋税三者牢牢绑定。自武德至天宝百余年间，它供养了数百万自耕农，撑起贞观之治与开元盛世。天宝以后，人口增殖、兼并炽盛，国家无地可授，籍帐失实，均田制名存实亡，终为建中元年两税法取代。",
    background: "隋末大乱，人口流散。隋大业五年（609年）全国在籍户数近八百九十万，至唐武德间仅余二百余万，黄河流域大面积抛荒，江淮亦多榛莽。田地无主，恰为国家直接掌握土地提供了前提。均田制并非唐代首创：北魏太和九年（485年），孝文帝已颁均田令，历经北齐、北周至隋，一脉相承。唐承隋制，在清丈土地、重造户籍的基础上，于武德七年（624年）颁行《田令》，将国家掌握的荒地授予农民。须指出，均田并不剥夺地主原有的私有土地，国家授出的只是无主荒地与官田，故其本质是国有与私有并行——这正是它日后瓦解的伏笔。",
    chapters: [
      {
        heading: "武德定制：百亩之制如何运作",
        paragraphs: [
          "武德七年（624年），唐高祖李渊颁行《田令》，均田制正式确立。其核心是按丁授田：丁男年十八以上，人授一顷（百亩），其中二十亩为永业田，可传子孙，身死不还；八十亩为口分田，死后归还官府，再行授受。老男与笃疾、废疾者授四十亩，寡妻妾三十亩，户主再增二十亩。土地宽裕的宽乡足额授给，人稠地狭的狭乡则减半或减三分之一授田，并鼓励农民从狭乡迁往宽乡。国家以此把战争抛荒的土地重新配置到耕作者手中。",
          "授田以户籍为据。基层百户为里，五里为乡，四家为邻，五家为保；州县每年核算户口与田亩，三年一造户籍，逐级上报州县与尚书省户部。田令对土地利用也有明文：永业田须于三年内种桑五十株、榆三株、枣五株以上，逾期未种则田收还官。田地原则上禁止买卖，唯迁徙、家贫无力办丧、户绝等情，方准卖永业田；口分田的限制更严。这些细密条文，皆为防止土地集中而设的闸门。",
          "均田制又是等级分明的体系。贵族与官僚另有永业田：亲王一百顷，正一品六十顷，递减至九品二顷；职分田充俸禄，去官即交还；州县另有公廨田作办公经费。道士、女冠、僧尼亦各授三十亩或二十亩。农民的百亩之田与亲王的百顷之田，同出一个田令：国家以授田换取农民的租庸调与官僚的效力。所谓均田，并非均尽天下之田，而是国家将手中无主荒地与官田，按身份与户等重新分配。"
        ]
      },
      {
        heading: "贞观至开元：盛世的经济基石",
        paragraphs: [
          "贞观初年，太宗李世民着力劝课农桑、检括户口。隋末战乱抛下的荒地，此时成为国家授田的凭借：流民归乡，编户齐民，自耕农数量猛增。武德间全国户数不足三百万，贞观中恢复至约三百八十万户，天宝十三载（754年）更达约九百万户。国家随之以丁为单位征收租庸调：每丁岁纳粟二石，称租；服役二十日，闰年加二日，不役者纳绢代役，称庸；纳绢二丈、绵三两，称调。数百万承担租调的课口，正是大唐财政的根基。",
          "均田制的本质，是国家以土地换取劳动力与赋税。农民受田百亩，须纳租庸调，并承担府兵兵役。府兵制同样以均田为根基：丁男入折冲府，轮番宿卫京师与边镇，自备弓矢衣粮。太宗、高宗两朝能破东突厥、平薛延陀、经营西域，兵锋所至，财力所聚，源头都在这一片片百亩之田。开元盛世仓廪丰实、户口鼎盛，亦是均田制运行百余年积累的成果。没有均田制，便没有贞观之治与开元盛世的物质底子。",
          "裂缝在高宗、武后以后逐渐张开。其一，人口增殖：自永徽至开元，户数几近翻番，国家掌握的荒地却授一分少一分，狭乡丁男只能授到三十亩、二十亩，甚至无地可授。其二，逃户：赋役沉重，农民弃田流亡，籍帐空悬。开元九年（721年），玄宗以宇文融为劝农使，括得逃户八十余万，随之括田。一次检括即得八十万户，既见朝廷维持均田的决心，也暴露制度已大量空转。盛世表章之下，均田制正渐渐失血。"
        ]
      },
      {
        heading: "天宝崩坏：无地可授与兼并之炽",
        paragraphs: [
          "开元、天宝之际，兼并之势已不可遏。王公百官与豪富之家广置庄田，恣行吞并：太平公主田园遍于近甸膏腴，李林甫、杨国忠等当朝权贵的田业亦跨州连县；寺院广占庄田，请田、借荒、包佃，名目繁多。天宝十一载（752年），玄宗下诏，直言王公百官及富豪之家比置庄田、莫惧章程，禁令形同虚文。国家手中无地可授，杜佑在《通典》中记天宝以后授田之制，已不能推行。百亩之田的还授循环，至此中断。",
          "均田制依赖严密的户籍。天宝年间，户籍已大量失实：田亩不登于籍，课口空有其名。安史之乱起，黄河流域残破，两京陷落，州县版籍散佚无存。朝廷莫说授田还田，连按丁征税都做不到，只能转而按亩、按户征敛，以充军兴。代宗大历年间，田令虽存，授田、还田与户籍清审均已停废，制度名存实亡。维系国家与农民的那条纽带，在战火中彻底断裂。",
          "建中元年（780年），唐德宗采纳宰相杨炎之议，颁行两税法：不再以丁身为本，一律按资产、土地征税，夏秋两征。这等于国家正式放弃按丁授田的旧轨，承认土地私有与兼并的现实——从前是先授田、后征税，如今地归谁已不必过问，只问田产几何。均田制由此退出历史舞台。此后王朝不再以国家力量重分土地，土地私有与租佃关系成为唐宋以降经济的基本形态。"
        ]
      }
    ],
    interpretation: "均田制的深层逻辑，是国家掌握荒地，授给农民，换取租庸调与兵役，把土地、户籍、赋税、兵役绑成一体。它成立的前提有二：国家手里有地，户籍清审严密。唐初两者齐备，故有贞观、开元之盛；天宝以后两者俱失，制度便成空壳。其瓦解方式尤堪注意：并非毁于兵火，而是被人口增殖与土地兼并慢慢掏空——这正是国家直接控制土地的内在限度。两税法以资产为税基，承认现实，征税不再以人身为本。中国由此从按丁授田、以人丁为本的国家，转向以田产为本的国家，影响至为深远。",
