      {
        heading: "胡将之议，遗患天宝",
        paragraphs: [
          "天宝六载，林甫进言：文臣为将，怯当矢石，不若用寒族胡人；胡人勇决习战，寒族孤立无党，陛下以恩洽其心，彼必为朝廷尽死。此议看似为边防选材，实为固位自保——此前张嘉贞、王忠嗣等皆由边将入相，林甫惧边帅立功拜相、重蹈前辙，遂以胡人代之，断其入朝之路，则己位可安。玄宗深然其说，自是安禄山一人兼范阳、平卢、河东三镇节度使，统兵十八万余，河北道精兵尽归其手。出将入相之制既坏，中央再无以制边镇。",
          "安禄山初入朝，林甫倾心结纳，约为父子。禄山桀黠，于诸宰相独惮林甫，每对之，虽隆冬亦汗流沾服，不敢稍逆，林甫亦以禄山为己外藩。天宝十一载十一月，林甫病卒于府中，年六十九，玄宗悼惜，赠太尉、扬州大都督。然不过两月，杨国忠继任，素衔林甫旧怨，遂发其生前交通回纥阿布思、阴图异端之事。帝震怒，诏剖棺抉取含珠，褫夺官服，以庶人礼改葬长安城南，子孙亲属流贬岭南、黔中者数十人。",
          "身后清算未已，边祸已至。天宝十四载（755）十一月，安禄山以讨杨国忠为名自范阳起兵，所统多胡骑蕃将，长驱南下，河北诸郡望风披靡。渔阳鼙鼓动地而来，惊破霓裳羽衣之曲，开元盛世积累的府库、甲兵、声威一夕倾覆。唐人论盛衰之变，追本溯源，多归咎于林甫蔽塞言路、引用胡将二事；《新唐书》修史，遂列林甫于《奸臣传》之首，以为千载炯戒。"
        ]
      }
