    interpretation: "李林甫居相位十九年，恰与开元盛世走向天宝颓势同步，其要害不在一人之贪，而在制度缝隙被其精准利用。玄宗晚年倦于万机，以顺旨代谏诤，林甫则以帝意为进退，君臣之间只剩揣摩与逢迎，言路、台谏、铨选层层失守。胡将之议为其诸事中影响最大者：唐初出将入相，边帅内调入朝，本是以相权节制边镇的纽带；林甫为安己位断此通路，边将遂不知朝廷、只知恩主。安禄山三镇兵马尽成私属，朝廷上下犹闻「野无遗贤」之贺。待林甫身死，矛盾总爆，盛唐遂不可复。故史家论唐之盛衰，未尝专责一人，而蔽贤固宠、变制坏法之责，林甫实无可辞。",
