    summary: "《全唐诗》是清圣祖玄烨敕修的唐五代诗歌总集，成书于康熙四十五年（1706）。由彭定求、沈三曾等十位翰林在扬州天宁寺诗局编校，江宁织造曹寅主持刊刻。全书九百卷，附目录十二卷，收唐五代诗四万八千九百余首、作者二千二百余家，并各系小传。此书虽成于清人之手，却是迄今规模最大的唐诗总集，李杜元白、王孟高岑之作赖以汇聚一堂，为后世诵读与研究唐诗最根本的渊海。",
    background: "康熙中叶，天下大定，圣祖玄烨以「稽古右文」为治国之策，既开博学鸿词科以网罗遗民，又敕修《朱子全书》《渊鉴类函》等巨帙，欲以文化之盛证明清廷承续道统。唐诗作一代之文学，清初诗坛又崇唐音，王士禛主盟坛坫，倡「神韵」之说，朝野风靡，汇辑全唐之诗遂成时代需求。文献积累亦至其时：明末胡震亨穷毕生之力辑成《唐音统签》一千三百余卷，清初季振宜以家藏珍本编成《唐诗》七百一十七卷，两书已具全唐诗规模。康熙四十四年（1705）三月，帝第五次南巡至苏州，遂颁旨以两书为底本编《全唐诗》，命江宁织造曹寅于扬州设局董其事。",
    chapters: [
      {
        heading: "敕修始末：天宁寺里设书局",
        paragraphs: [
          "康熙四十四年（1705）三月，圣祖第五次南巡，驻跸苏州。彼时天下承平已久，帝留心文治，遂颁旨编纂《全唐诗》，将修书之事交由江宁织造曹寅，命其在扬州天宁寺开设诗局，并调集在籍翰林十人入局编校。曹寅出身内务府包衣，长期担任两淮巡盐御史、江宁织造，实为皇帝安插江南的耳目，又雅好诗文、广交名士，由其董理此事，既因物力充足，也因其能在江南士林中居间联络。",
          "入局的十位翰林为彭定求、沈三曾、杨中讷、潘从律、汪士鋐、徐树本、车鼎晋、汪绎、查嗣瑮、俞梅。彭定求为康熙十五年（1676）状元，汪绎为康熙三十九年（1700）状元，十人皆进士出身，曾任翰林院编修、检讨之职，故世称「十翰林」。书局既动用内帑，又有两淮盐课的财力做后盾，编纂条件之优渥，历代私家总集难以望其项背。",
          "编纂以胡震亨《唐音统签》与季振宜《唐诗》为底本，参以《文苑英华》《唐诗纪事》等书，校雠补缀。自康熙四十四年五月开局，至四十五年（1706）十月全书告成进呈，前后仅一年有半，成书之速在大型总集中罕见。康熙帝亲撰《御制全唐诗序》冠于书首，序中言及得诗四万八千九百余首、作者二千二百余人，即出自进呈之数。"
        ]
      },
      {
        heading: "卷帙规模：四万八千九百首",
        paragraphs: [
          "《全唐诗》共九百卷，附目录十二卷，编次以时代为经、作者为纬：首列帝王后妃，次乐府，再次各家诗人，按生平先后大体排定，方外、闺秀、仙鬼之类附于末。又为二千二百余位作者各系小传，简介字号、籍贯、仕历与著述，虽简略，却使一代诗人灿然具备眉目，翻检一过，便是一部唐诗简史。",
          "全书收录诗歌四万八千九百余首，上自隋唐之际，下讫五代十国，三百余年间留存篇什几乎网罗殆尽。李白、杜甫、白居易各家均有专卷：李白诗近千首，杜甫诗一千四百余首，白居易诗近三千首，皆依底本完整收录。唐五代诗人别集散佚过半，许多中小作者仅靠《全唐诗》才保存下只鳞片爪，否则早已湮没无闻。",
          "刻工亦为一时之选。扬州诗局召集良工写刻上版，校写俱精，纸墨考究，世称「诗局本」，为清代写刻本的典范。康熙四十六年（1707）刻竣颁行后，翻刻、石印、排印不绝，此后二百年间士人读唐诗，几乎人手一编，成为最通行的标准文本。"
        ]
      },
      {
        heading: "千秋功过：宝库亦有遗珠",
        paragraphs: [
          "以一年半之期成九百卷之书，求速则难免疏漏，其弊约有数端：一曰误收，唐以前或宋以后之诗窜入其中；二曰重出，一首两见、一人两传者不少；三曰漏收，敦煌遗书所出唐佚诗及《全唐诗逸》所载之外尚多；四曰小传舛误，于作者仕历往往因袭旧说，未及详考。凡此种种，后人屡有指摘，清代学者如钱大昕、近代学者如岑仲勉，皆曾纠谬。",
          "然其功终不可没。胡震亨、季振宜两家之书虽具规模，终属私辑，未通行于世；《全唐诗》以帝王之力、国家之财，将唐五代诗歌汇为一编，刊布天下，实为保存唐诗文献的第一大功臣。此后敦煌遗书出世、佚诗重见天日，王重民、孙望、童养年等辑《全唐诗补编》，补诗数千首，仍不过是这座宝库的补苴罅漏，而非另起炉灶。",
          "今通行本为中华书局1960年点校本，以诗局本为底本，参校众本，标点排印，读者咸便之。千年之后，唐人诗作仍诵于儿童之口、研于学者之案，《全唐诗》为之总汇，其沾溉后学，可谓深且远矣。"
        ]
      }
    ],
    interpretation: "《全唐诗》之修，非仅文学盛事，实为清廷文治之一环。圣祖以异族入主中原，武功既盛，必以文教证明承续道统；开博学鸿词、修《朱子全书》，与此书同一机杼。将一代之诗悉收御府，既示「稽古右文」之姿，亦寓笼络江南士林之意——书局设于扬州，主持者曹寅乃皇帝家臣，入局者多为江南汉族翰林，恩威并施，皆在其中。就文献而言，此书成于唐集散佚之后，胡震亨、季振宜两家的积累借皇家之力化为公器，唐诗因之得以整体传世。后世虽有补编、校注，皆立于其肩。",
