    interpretation: "宋璟的政治价值，在于以「法」与「礼」约束皇权与权贵。武周以来，恩幸干进、请托成风，宰相或以权变固位，或以阿附取容。宋璟反其道而行，为相不用私人、不避权幸、犯颜忤旨，把开元初年的治理从权宜之计拉回律令礼制的轨道。他与姚崇一守常一应变，恰成互补：姚崇开局面，宋璟立规矩。其罢相亦具象征意味：玄宗为安定商贾而罢持正之相，天宝以后人主渐以私欲掩蔽制度，直臣日远，佞幸日近。故宋璟之进退，实为开元盛世由盛转衰之一伏笔。文贞之谥、「姚宋」之名，皆为唐代士大夫立一标杆。",
