    dynasty: "唐",
    era: "开元二十六年",
    year: {
      start: 738
    },
    summary: "《唐六典》三十卷，唐玄宗开元十年（722年）下诏修撰，开元二十六年（738年）成书，由张说、张九龄、李林甫等先后主持，集贤院学士徐坚、韦述等参与编修。全书仿《周礼》六官之制，分理、教、礼、政、刑、事六典，系统记述唐代三师三公、三省六部、九寺五监至州县乡里各级官署的设置、员额、品阶与职掌，并附列汉魏以来沿革。它是现存最早、最完整的古代行政法典，与《唐律疏议》并称唐代典章的双璧，对后世及东亚诸国官制影响深远。",
    background: "开元初年，唐玄宗先后任用姚崇、宋璟为相，整饬吏治，淘汰冗员，至开元十年前后，府库渐充，四夷宾服，海内富庶，史称开元之治。然自贞观至武周、中宗以来，官制屡有增省，三省六部、九寺五监与各类使职差遣并行，员额、品阶、职掌多有淆乱，百官行政往往因人设官、因事置使。玄宗欲使官有常员、职有常守，遂于开元十年亲写六条于集贤院，名之为理、教、礼、政、刑、事六典，命起居舍人陆坚与集贤院学士徐坚、韦述、贺知章等修撰。此书以《周礼》六官为法，欲将本朝现行官制与三代理想治法贯通于一编，以正百官之职，明朝廷之制，这便是《唐六典》的缘起。",
    chapters: [
      {
        heading: "敕修集贤",
        paragraphs: [
          "开元十年（722年），唐玄宗在位已逾十年，天下殷富，正是制度整备之时。玄宗于集贤院亲书六条，即理典、教典、礼典、政典、刑典、事典，作为全书纲领，命起居舍人陆坚领其事，集贤院学士徐坚、韦述、贺知章等参与修撰。其用意不仅在于汇辑现行官制，更欲上溯《周礼》六官之意，使唐代制度与三代圣王之治遥相承接，从而宣示开元政治的正统与规模。",
          "修撰之事历时漫长，前后近二十年，主持者屡易其人。开元十三年张说罢相后，仍以集贤院学士身份主持其事；徐坚、韦述等苦心搜讨，因体例难定，书久不成。张说于开元十八年（730年）去世后，修撰并未中辍，张九龄、李林甫相继以宰相之职总其事，集贤院学士持续补缀考订，至开元二十六年（738年）始克成书。",
          "书成三十卷，次年即开元二十七年（739年）二月，中书令李林甫奏上注表，进献于朝。自开元十年诏修至此，历时十七年，历经三任宰相主持、十余位学士之手，在中古官修典籍中，其用力之深、历时之久，亦属少见。书成之后藏于秘阁，颁行天下，成为有唐一代明示百官职掌的行政大典。"
        ]
      },
      {
        heading: "六官为体",
        paragraphs: [
          "《唐六典》三十卷，表面上仿照《周礼》六官分门，实则以唐代现行官制为骨架。卷一至卷三述三师、三公、尚书都省及吏、户、礼、兵、刑、工六部，卷四至卷十述门下、中书、秘书、殿中等省及御史台，卷十一以下分述太常、光禄、卫尉、宗正、太仆、大理、鸿胪、司农、太府九寺与国子、将作、军器等监，其后依次为地方州县官、镇戍关津官、内外命妇及致仕官制，自朝廷至乡里，井然贯通。",
          "全书以官名为目，每一官署先列其名、次载员额品阶，再详述职掌。正文记开元年间现行之制，注文则追溯秦汉魏晋以来沿革，上下千余年制度变迁粲然可见。如叙中书省，则自汉武帝游宴后庭、宦者典尚书事起，历魏晋中书监省之设，至唐代舍人六员之制，本末兼赅，使读者既知当朝所行，又明其所自来。",
          "其以《周礼》六官为名，是托古而非泥古。《周礼》六官体系本非唐代所行，编者借六典之名分门类事，实际内容尽是有唐现行官署。这种以古制为表、今制为里的编排，既满足了玄宗追摹三代的政治理想，也完整保存了开元一朝的实际行政架构，可谓匠心独具。"
        ]
      },
      {
        heading: "行政之法",
        paragraphs: [
          "若说《唐律疏议》是唐代的刑律大典，那么《唐六典》就是唐代的行政法典。律管罪名刑罚，六典则管设官分职：某官几员、几品、俸禄几何、掌管何事、如何考核、如何迁转，皆有明文。州县官的户口、赋役、刑狱之责，诸监的营造、盐铁、仓储之务，以及官吏的请假、致仕、丧葬待遇，条分缕析，构成一套完整的行政规章体系。",
          "书中所载，并非纸面空文，而是开元年间实际运行的制度。三省六部的权力配置、使职差授的员额、府兵制下的武官体系、均田租庸调下的基层政务，都真实反映了盛唐时期的行政运作。特别是它详于基层：里正、坊正、镇戍、关津官员的职掌员额皆有记录，为后世了解唐代基层社会保存了第一手材料。",
          "《唐六典》还与《唐律疏议》互为表里。律文中常见『违式』『违令』之罪，其处罚须以式令为据，而六典所载正是这些式令的渊源所自。两者一主刑罚、一主行政，共同构成唐代法制大厦的两根支柱，后世合称『律令格式』之治，六典实为其行政一端的总汇。"
        ]
      },
      {
        heading: "流泽千载",
        paragraphs: [
          "《唐六典》成书后，历经唐末五代兵燹，至宋代仍有传本。北宋元丰年间改革官制，即取《唐六典》为考镜沿革之资；南宋绍兴四年（1134年）温州州学刻本，为今存最早刊本，历代递相翻刻，使此书得以完整流传至今，现藏于国家图书馆，成为研究唐代典章制度的核心文献。",
          "其影响不限于一代。明代《大明会典》、清代《大清会典》，以会典之名记载一代官制职掌，体例虽有所变，精神实承《唐六典》而来，皆是以官署为纲、以职掌为目、附载沿革的行政典章。可以说，自唐以降历代中央行政法的编纂，都沿着六典开辟的路径演进，形成中国独有的会典传统。",
          "《唐六典》还远播域外。日本《养老令》中的职员令，朝鲜半岛历代官制，多参酌唐代典章；新罗、渤海遣使入唐，所学制度亦多载于此书。二十世纪以来，日本与欧美学者研究唐代官僚制度，无不以《唐六典》为基本依据，这部开元年间修成的行政法典，至今仍是理解中华古代国家治理的一把钥匙。"
        ]
      }
    ],
    interpretation: "《唐六典》的深层逻辑，在于以复古为革新。玄宗亲定六典之名，托《周礼》六官之古制，载开元现行之实政，既为变动不居的唐代官制赋予三代圣王的政治正统性，也为权力运作划定制度边界。它把设官分职、员额品阶、职掌考核全部文本化，使百官有章可循、朝廷有据可考，体现了盛世制度化的努力。它上承《周礼》理想，下启宋元明清会典之制，更东被日本、朝鲜，成为东亚行政法传统的共同源头。一部行政法典而能贯通千年、跨越邦国，其价值早已超出唐代一朝，而成为理解中国古代国家治理的枢纽性文献。",
