    interpretation: "颜真卿一生，正值唐王朝由盛转衰。安史之乱中，河北二十四郡几尽降贼，唯平原、常山以书生当危难，首举义旗，可见唐代士大夫气节未坠。其牵制叛军，使朝廷得集朔方之师，于平叛全局功不可没。其死实非个人悲剧：卢杞以借刀杀人之计出之，朝堂党争之酷、君相之暗，于此可见；而李希烈跋扈、藩镇之祸，更见中晚唐中央衰弱之局。其书法所以雄强浑厚，正与人格相表里。宋人特重其人，苏轼以「书至于颜鲁公」为极则，自此书品与人品合一，遂为中国书法审美之重要传统。颜体楷书笼罩千年，今人学书，犹以颜字为入门正格。",
