    summary: "杨国忠（？—756），本名杨钊，蒲州永乐（今山西永济）人，杨贵妃堂兄。早年落魄蜀中，天宝间因贵妃得宠而骤贵，由度支郎中不次超擢至右相，身兼四十余使，总揽财政与铨选，专权纳贿，朝政大坏。两次兴师征南诏，丧师近二十万。与范阳节度使安禄山争权不休，逼成叛乱。天宝十五载（756）六月，扈从玄宗西奔入蜀，至马嵬驿为哗变禁军斩杀，身死族灭，为唐代外戚专权乱政之极。",
    background: "开元末年，玄宗在位已逾三十年，天下承平，府库充盈，帝渐倦于政事，委政于李林甫。开元二十八年（740），寿王妃杨氏入宫，天宝四载（745）册为贵妃，恩宠冠绝后宫，杨氏一门骤贵，姊妹三人皆封国夫人。杨国忠本名杨钊，少嗜酒好赌，为宗党所轻，发愤从军，客游蜀中十余载，授新都尉，考满家居，贫不能自存。会从祖妹杨玉环得幸，剑南节度使章仇兼琼欲结贵妃为内援，闻国忠为贵妃从祖兄，乃遣入京，厚遗之，授金吾兵曹参军。国忠仪观甚伟，口辩给，善窥帝意，以聚敛进身，迎合帝好货之心，岁入大增，帝以为能，故不次超擢。其骤兴之源，实在玄宗暮年怠政、宠任外戚与聚敛之臣，非尽国忠一人之过也。",
    chapters: [
      {
        heading: "蜀中落魄，骤贵天宝",
        paragraphs: [
          "杨国忠本名杨钊，蒲州永乐人，父珣，官卑不显。国忠少无行，嗜酒善博，宗党皆轻之。发愤从军，在蜀十载，授新都尉，考满家居，贫不能自存，赖富蜀鲜于仲通等接济。会从祖妹杨玉环得幸玄宗，天宝四载册为贵妃，恩宠冠于后宫，杨氏一门皆蒙恩泽。剑南节度使章仇兼琼欲固位，知国忠为贵妃从祖兄，乃使之入京，厚遗货宝，授金吾兵曹参军。国忠既至长安，以贵妃故得出入禁中，日见亲信。",
          "国忠性强辩，敢大言，善揣帝意所向而迎之。时玄宗以天下富庶自矜，国忠曲意聚敛，岁入大增，帝以为贤。天宝七载（748），擢度支员外郎，兼侍御史；不数年迁度支郎中，自户部、度支、盐铁以至吏部铨选，一身总之，领使四十余，权倾天下，百司皆仰其鼻息。性又忌刻，凡不附己者必以计去之，赂遗至者辄超擢，朝士趋附其门，台省要职多出其门下，公行贿赂，家赀巨万，第舍华侈，拟于宫掖，而人莫敢言。"
        ]
      },
      {
        heading: "聚敛固宠，丧师南诏",
        paragraphs: [
          "国忠以宰相兼判度支、吏部三铨，选人无问贤愚，但纳赂即补，墨敕斜封之弊复见于天宝。玄宗在位久，怠于万机，悉以政事委之，国忠因得上下其手。性疏躁，不学无术，然善伺候帝颜色，所言无不合旨，恩泽日深。御史中丞宋浑等党附之，表里为奸，台臣莫敢忤。朝野侧目，而帝不悟，反以为忠勤。国忠自知以恩幸进，群情不附，欲立边功以示威名，固其权宠，遂谋用兵西南。",
          "天宝十载（751），剑南节度使鲜于仲通将兵八万讨南诏，阁罗凤诱之深入，败于西洱河，死者六万。十三载（754），剑南留后李宓复将兵七万进讨，粮尽矢绝，深入瘴疠，全军覆没，宓死之。两役合丧师近二十万，举国骚然，关中大扰，丁壮尽死于南荒，国中无复可用之兵。国忠掩败为功，更以捷闻，益加赏擢，人怨之而不敢言。识者知天下将乱，禄山之徒益轻朝廷矣。"
        ]
      },
      {
        heading: "激成叛乱，马嵬殒命",
        paragraphs: [
          "范阳节度使安禄山久蓄异志，兼平卢、河东、范阳三镇，拥兵十八万，威权震主，中外侧目。禄山本轻国忠，及国忠为相，互争权柄，水火不相容。国忠数言禄山必反，帝弗听；国忠乃逼之益急，遣京兆尹围捕其第，籍其党与，奏请罢其兵权。禄山惧，遂于天宝十四载（755）十一月起兵，以讨国忠、清君侧为名，兵锋直指两京。河北州县望风瓦解，封常清、高仙芝连败，帝始思国忠之言。",
          "十五载正月，禄山僭称帝于洛阳。六月，哥舒翰兵败潼关，二十万军溃，国忠劝帝弃长安西幸入蜀。丙申，车驾至马嵬驿，将士饥疲，六军不发。左龙武大将军陈玄礼密启太子，诛国忠。乱兵呼曰「杨国忠通胡，与吐蕃谋反」！国忠走马至驿门，为军士追及斩之，屠割其尸，士卒争食其肉，须臾而尽，揭其首于驿门。子杨暄及韩国、秦国夫人皆死，贵妃亦缢死于路祠。帝仅以身免，西入蜀郡，唐室由是衰矣。"
        ]
      }
    ],
    interpretation: "杨国忠之起，源于玄宗暮年怠政、宠任外戚；其败，源于以聚敛邀宠、以边功固位，终至不可收拾。国忠未尝一日临民治军，徒以贵妃之故，骤致相位，领使四十余，财政、铨选并归一人，制度之防尽失。征南诏而丧师二十万，竭天下之力以充其欲；激禄山而速其反，弃两京而西奔。马嵬之变，六军不发，兵发于久怨，国忠身死族灭，贵妃继之，唐室由盛转衰。故史家论天宝之乱，虽成于禄山，实酿于李林甫、杨国忠之专权，而其本则在玄宗之骄怠。外戚、聚敛、藩镇三弊交集，国忠一身兼之，宜其及于难也。",
