    name: "《贞观政要》",
    pinyin: "zhenguanzhengyao",
    aliases: [],
    dynasty: "唐",
    era: "开元八年",
    year: {
      start: 720
    },
    summary: "《贞观政要》是唐代史官吴兢所撰的政论性史书，约成于开元八年（720年）前后。全书十卷四十篇，分类辑录唐太宗李世民与魏征、房玄龄、杜如晦、王珪等人的问答、谏诤与诏敕，内容涵盖君道、任贤、求谏、纳谏、择官、务农、刑罚、封建、征伐、慎终等，系统总结贞观一朝的政治得失。吴兢编纂此书，意在以贞观之治为帝王取法，进呈玄宗。后世帝王奉为治国圭臬，唐宣宗书于屏风，宋仁宗命侍臣进读，日本幕府亦推重之，成为东亚世界共同的政治经典。",
    background: "开元初年，唐玄宗李隆基诛除太平公主集团，亲政之后勤于理政，任用姚崇、宋璟，整顿吏治，抑制奢靡，开元年间的唐朝迅速走出武周革命以来数十年的宫闱动荡，国势复振。然而承平日久，朝廷渐见因循，奢逸之风潜滋暗长，边事、冗官与财政之弊初露端倪。吴兢其时任史官，久在史馆，得以遍阅本朝实录、起居注与诏敕，深感国家治乱系于君心之敬肆，遂有意取贞观遗范规谏当朝。贞观之治距开元不足百年，太宗克己纳谏、魏征犯颜直谏的故事犹在人口，是当时朝野公认的政治典范。吴兢将贞观君臣的言行按问题分类纂辑，既是对一代治世的追慕，更是以史为谏，望玄宗法祖图治，不使盛世得而复失。",
    chapters: [
      {
        heading: "十卷四十篇",
        paragraphs: [
          "全书十卷四十篇，篇目依类编排，自《君道》《政体》发端，继以《任贤》《求谏》《纳谏》《君臣鉴戒》论用人听言，又列《择官》《封建》《太子诸王定分》《教戒太子诸王》论百官宗室储君，再及《仁义》《忠义》《孝友》《公平》《诚信》《俭约》《谦让》诸篇陈伦理风俗，而以《务农》《刑罚》《赦令》《贡赋》《辩兴亡》《征伐》《安边》综理军国大政，终以《慎终》收束，告诫守成之难。这一体例由近及远、由内而外，从君心推及天下，构成一部完整的帝王政治学纲领。",
          "各篇皆以事系言，分类辑录太宗与群臣的问答、谏诤与诏敕，不按年月编排，而按问题归聚，便于帝王随事翻检、按类取鉴。所涉人物除魏征、房玄龄、杜如晦外，尚有王珪、李靖、虞世南、褚遂良、马周、戴胄等，几乎囊括贞观名臣。书中所载大多可与两《唐书》《资治通鉴》相印证，亦有若干内容为他书所不载，史料价值与思想价值并重。",
          "书中名节甚多。贞观二年（628），太宗问魏征何为明君、何为暗君，魏征以「兼听则明、偏信则暗」作答；贞观六年，群臣请封禅，魏征以民生未复、府库未实谏止；同年关中大旱，太宗亲览冤狱，于禁苑中吞蝗，自陈「百姓有过，在予一人」。这些片段分别归入《君道》《政体》《务农》《刑罚》各篇，使太宗的施政形象与贞观一朝的政治风气跃然纸上。"
        ]
      },
      {
        heading: "以史为谏",
        paragraphs: [
          "吴兢，汴州浚仪人，励志勤学，博通经史，武则天时入史馆，与刘知几、徐坚等同修《则天实录》。他亲历武周以来的宫闱动荡与神龙、景龙间的政变频仍，深感国家治乱系于君心之敬肆。开元之初，玄宗扫平太平公主，励精图治，天下渐趋殷富；然承平日久，渐生骄逸，吴兢遂以史官身份，取贞观遗范进谏。",
          "吴兢得以遍阅史馆所藏《太宗实录》、起居注与诏敕奏议，遂于开元八年（720）前后纂成此书，进呈玄宗。其自序称「太宗时政化，良足可观，振古而来，未之有也」，又说编集此书是为了保存贞观善政，使后世帝王有所取法。书成之后，吴兢并未因此而显达，仍以修史为务，其为人方直、无所阿附的品格，贯穿于全书的选材之中。",
          "吴兢修《则天实录》时直书张昌宗劝诱魏元忠事，张说阅后深感其直笔。这种秉笔直书的史家气质，同样见于《贞观政要》：书中于太宗的悔过、奢纵、贪鄙之失并不回避，专列《悔过》《奢纵》《贪鄙》《慎终》诸篇，正是要帝王以过失为戒，而非仅以美言自饰。书为谏而作，于此可见。"
        ]
      },
      {
        heading: "帝王之鉴，东传日本",
        paragraphs: [
          "《贞观政要》进呈后，并未立即成为显学，中唐以后渐受推重。唐宣宗李忱书《贞观政要》于屏风，朝夕省览；宋仁宗赵祯命侍臣进读，以为治国准绳；辽圣宗、金熙宗亦命译为契丹、女真文字以教贵族。元代戈直搜罗诸本，撰成《贞观政要集注》进呈，此后明清两代刊刻不绝，几为帝王必读之书。",
          "此书约在九世纪传入日本，平安时代即藏于皇家与贵族文库。嵯峨天皇、清和天皇命侍讲进读，藤原氏与江户幕府亦列为将军及世子读物。德川家康曾命僧以明代刊本讲授于幕府，日本至今保存多种古抄本，为校勘提供珍贵依据。一部唐代的帝王教科书，由此成为东亚共同的政治经典。",
          "从文献源流看，此书所记多可与《旧唐书》《新唐书》《资治通鉴》相互印证，亦有若干内容为他书所不载，为研究贞观政治提供了独特材料。但须注意，吴兢的编纂目的在于取法与规谏，取材有所选择，重在可资鉴戒的言行，并非贞观朝历史的完整记录。读此书既要见其史料，也要知其用心。"
        ]
      }
    ],
    interpretation: "《贞观政要》看似修史，实为进谏。吴兢生当开元盛世初显之时，却已感到承平之下潜伏的骄逸之机，于是把贞观君臣的问答、诏敕按问题重新编排，造成一部可以随时翻检对照的帝王操作手册。它把贞观之治的成功归结为两点：君能纳谏、臣敢直谏，即君道与臣道的相互成就。这一总结抓住了古代政治的核心，权力若无约束，制度若无操持者，便会迅速败坏。但此书的局限也正在于此，它把治乱寄托于君心之敬肆、臣节之忠直，未能从制度上回答如何约束权力。贞观之后，唐代终因藩镇、宦官与党争而衰，恰说明明君贤臣的人治不可恃。尽管如此，此书所建构的纳谏、任贤、慎终、务本的帝王政治理想，仍深刻塑造了后世东亚的政治观念，其影响已超出史书范畴。",
