      {
        heading: "安史惊变：法度崩坏",
        paragraphs: [
          "天宝十四载（755）十一月，安禄山起兵范阳，两京陷落，玄宗西幸，海内沸腾。战火所过，州县残破，百姓流亡，版籍散失殆尽。乾元以后户数骤减，广德二年（764）全国仅余约二百九十余万户，较天宝十四载锐减三分之二以上。藩镇割据于河朔，朝廷赋入唯仰江淮、剑南等东南八道，而军兴烦急，旧日按丁征敛之法，既无丁可据，亦无籍可凭。",
          "更深层的变化在乡里。均田既坏，庄田盛行，地主、官宦、寺院广占田土，失地农民依附权门，名为「客户」，不入国家户籍。租庸调以丁为本，而丁随田走，田在私门，朝廷所掌空有其名。代宗朝刘晏理财，以盐利赡军，已开别辟财源之路；元载、杨炎先后秉政，皆知旧制不可复行。朝廷为应急需层层加征，地方多取于民，而正赋所入日少，财政困局愈深。",
          "建中元年（780），宰相杨炎奏行两税法，废租庸调与一切杂徭，分夏秋两征，「户无主客，以见居为簿；人无丁中，以贫富为差」，征税标准自人丁转向户、田。自武德七年至此一百五十余年，租庸调正式退出历史舞台。自兹以后，唐代财政彻底由计丁取税转入计亩取税之新轨，两税法虽应时而生，然以钱定税、折纳纷繁，又启后世税外加征之弊，此是后话。"
        ]
      }
