    interpretation: "租庸调制的兴衰，实为一部以人丁为本的财政实验。其设计逻辑是：国家授田于民，民报之以租庸调，权利与义务对称，理论上官民两利。它能行于初唐、盛唐，全因均田未坏、户籍可信；其崩于中唐，亦非法之弊，乃田制之坏。庸以绢代役一项，在中国财政史上尤具开创意义：它把劳役转化为实物，既解放了农民的劳动时间，又为后世以田亩、资产承担役银埋下伏笔。从长时段看，北魏均田、唐租庸调、唐德宗两税法、明一条鞭法乃至清摊丁入亩，构成一条从计丁走向计田的长链。两税法正是此链的关键一环，国家财政自此渐次放弃对人身的直接控制，转而丈量土地、按资产课税，这一转向影响中国此后一千年。",
